<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { Head, Link } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

interface Row { enrollment_id:number; nis:string; student_name:string; class_name:string; subject_name:string; materials_read:number; materials_total:number; assignments_submitted:number; assignments_total:number; late_count:number; revision_count:number; average_score:number|null }
const props = defineProps<{ active_term?: { name:string } | null; rows: Row[]; personal_attendance?: {present:number;sick:number;permitted:number;absent:number;total:number;percentage:number}|null }>();
const search = ref('');
const selectedClass = ref('');
const classes = computed(() => [...new Set(props.rows.map(r => r.class_name))].sort());
const filtered = computed(() => props.rows.filter(r => (!selectedClass.value || r.class_name === selectedClass.value) && `${r.nis} ${r.student_name} ${r.subject_name}`.toLowerCase().includes(search.value.toLowerCase())));
const totals = computed(() => ({ students: new Set(filtered.value.map(r => r.enrollment_id)).size, material: filtered.value.reduce((n,r) => n+r.materials_read,0), task: filtered.value.reduce((n,r) => n+r.assignments_submitted,0), late: filtered.value.reduce((n,r) => n+r.late_count,0) }));
const ratio = (done:number,total:number) => total ? Math.round(done/total*100) : 0;
</script>

<template><Head title="Progress Belajar"/><AppLayout><main class="view space-y-6 learning-progress-page"><section class="hero-card compact-hero"><div><p class="eyebrow">Monitoring pembelajaran · {{ active_term?.name ?? 'Belum ada semester aktif' }}</p><h1>Progress belajar siswa</h1><p>Pantau materi dibaca, tugas selesai atau terlambat, kebutuhan revisi, dan capaian nilai.</p></div><Link class="secondary-button" href="/pembelajaran">Kembali ke pembelajaran</Link></section>
<section class="grade-summary"><div><span>Siswa</span><strong>{{ totals.students }}</strong><small>pada hasil filter</small></div><div><span>Materi dibaca</span><strong>{{ totals.material }}</strong><small>aktivitas tercatat</small></div><div><span>Tugas selesai</span><strong>{{ totals.task }}</strong><small>pengumpulan tercatat</small></div><div><span>Terlambat</span><strong>{{ totals.late }}</strong><small>perlu perhatian</small></div></section>
<section v-if="personal_attendance" class="panel personal-attendance"><div><span>Kehadiran saya</span><strong>{{ personal_attendance.percentage }}%</strong></div><p>Hadir {{ personal_attendance.present }} · Sakit {{ personal_attendance.sick }} · Izin {{ personal_attendance.permitted }} · Alpa {{ personal_attendance.absent }}</p></section>
<section class="panel overflow-hidden"><div class="toolbar progress-toolbar"><input v-model="search" placeholder="Cari siswa atau mata pelajaran"><select v-model="selectedClass"><option value="">Semua kelas</option><option v-for="c in classes" :key="c">{{ c }}</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Siswa</th><th>Kelas / Mapel</th><th>Materi</th><th>Tugas</th><th>Terlambat</th><th>Revisi</th><th>Rerata nilai</th></tr></thead><tbody><tr v-for="row in filtered" :key="`${row.enrollment_id}-${row.subject_name}`"><td><strong>{{ row.student_name }}</strong><br><small>{{ row.nis }}</small></td><td>{{ row.class_name }}<br><small>{{ row.subject_name }}</small></td><td><strong>{{ row.materials_read }}/{{ row.materials_total }}</strong><br><small>{{ ratio(row.materials_read,row.materials_total) }}%</small></td><td><strong>{{ row.assignments_submitted }}/{{ row.assignments_total }}</strong><br><small>{{ ratio(row.assignments_submitted,row.assignments_total) }}%</small></td><td>{{ row.late_count }}</td><td>{{ row.revision_count }}</td><td><strong>{{ row.average_score === null ? '—' : `${row.average_score}%` }}</strong></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty-state">Belum ada data progress untuk filter ini.</td></tr></tbody></table></div></section></main></AppLayout></template>

<style scoped>.compact-hero{display:flex;align-items:center;justify-content:space-between;gap:1rem}.progress-toolbar{display:flex;gap:.75rem;padding:1rem 1.25rem;border-bottom:1px solid #e2e8f0}.progress-toolbar input{flex:1}.progress-toolbar input,.progress-toolbar select{border:1px solid #cbd5e1;border-radius:.65rem;padding:.65rem .75rem}.table-wrap{overflow:auto}.data-table small{color:#64748b}.empty-state{text-align:center;padding:3rem;color:#64748b}.personal-attendance{display:flex;justify-content:space-between;align-items:center;padding:1rem 1.25rem}.personal-attendance span{display:block;color:#64748b;font-size:.78rem}.personal-attendance strong{font-size:1.5rem;color:#4338ca}@media(max-width:760px){.compact-hero{align-items:stretch;flex-direction:column}.progress-toolbar,.personal-attendance{align-items:stretch;flex-direction:column}}</style>
